"""Intent tests for mdata.align_calendar: one calendar, forward fill, and a gap limit (DATA-03, DATA-04)."""

from __future__ import annotations

import re

import pytest

import mdata
from mdata import Prices, RawRow, align_calendar


def _rows(payload: dict) -> list[RawRow]:
    return [RawRow(date=date, ticker=ticker, close=close) for date, ticker, close in payload["rows"]]


@pytest.mark.intent
def test_tc02_calendar_starts_when_every_ticker_has_a_close_and_gaps_take_previous_close(golden):
    payload, expected = golden("mdata", "TC-02")

    prices = align_calendar(_rows(payload), max_gap=payload["max_gap"])

    assert isinstance(prices, Prices)
    assert list(prices.dates) == expected["dates"]
    assert list(prices.tickers) == expected["tickers"]
    assert set(prices.closes) == set(expected["closes"])
    for ticker, closes in expected["closes"].items():
        assert list(prices.closes[ticker]) == closes, ticker


@pytest.mark.intent
def test_tc02_result_is_independent_of_row_order(golden):
    payload, expected = golden("mdata", "TC-02")

    prices = align_calendar(list(reversed(_rows(payload))), max_gap=payload["max_gap"])

    assert list(prices.dates) == expected["dates"]
    assert list(prices.tickers) == expected["tickers"]
    for ticker, closes in expected["closes"].items():
        assert list(prices.closes[ticker]) == closes, ticker


@pytest.mark.intent
def test_tc02_default_max_gap_aligns_the_same(golden):
    payload, expected = golden("mdata", "TC-02")

    prices = align_calendar(_rows(payload))

    assert list(prices.dates) == expected["dates"]
    for ticker, closes in expected["closes"].items():
        assert list(prices.closes[ticker]) == closes, ticker


@pytest.mark.intent
def test_tc03_six_date_gap_raises_gap_error_naming_the_ticker(golden):
    payload, expected = golden("mdata", "TC-03")
    error = getattr(mdata, expected["raises"])

    with pytest.raises(error, match=re.escape(expected["match"])):
        align_calendar(_rows(payload), max_gap=payload["max_gap"])


@pytest.mark.intent
def test_tc03_default_max_gap_is_five(golden):
    payload, expected = golden("mdata", "TC-03")
    error = getattr(mdata, expected["raises"])

    with pytest.raises(error, match=re.escape(expected["match"])):
        align_calendar(_rows(payload))

